export type ShiftId = 'early' | 'late' | 'night' | 'leave'

/** What fills one person's day: a shift, leave, or nothing (off) */
export type Assignment = ShiftId | null

export interface Shift {
  id: ShiftId
  label: string
  /** One letter, shown in the cell and typed to assign it */
  code: string
  time: string
  /** Start and end in hours from midnight of the shift's own day */
  start: number
  end: number
  /** Paid hours. Leave counts toward the contract but covers nothing. */
  hours: number
}

export const shifts: Shift[] = [
  {
    id: 'early',
    label: 'Early',
    code: 'E',
    time: '06:00–14:00',
    start: 6,
    end: 14,
    hours: 8,
  },
  {
    id: 'late',
    label: 'Late',
    code: 'L',
    time: '14:00–22:00',
    start: 14,
    end: 22,
    hours: 8,
  },
  {
    id: 'night',
    label: 'Night',
    code: 'N',
    time: '22:00–06:00',
    start: 22,
    end: 30,
    hours: 8,
  },
  {
    id: 'leave',
    label: 'Leave',
    code: 'A',
    time: 'Annual leave',
    start: 0,
    end: 0,
    hours: 8,
  },
]

export const shiftById = Object.fromEntries(
  shifts.map((s) => [s.id, s]),
) as Record<ShiftId, Shift>

/** The shifts a ward has to staff, in order */
export const covered = ['early', 'late', 'night'] as const
export type CoveredShift = (typeof covered)[number]

export interface Day {
  id: string
  /** "Mon" */
  short: string
  /** "23" */
  date: string
  weekend: boolean
}

// Fixed strings, not Date formatting, so the server and browser agree
export const days: Day[] = [
  { id: 'mon', short: 'Mon', date: '23', weekend: false },
  { id: 'tue', short: 'Tue', date: '24', weekend: false },
  { id: 'wed', short: 'Wed', date: '25', weekend: false },
  { id: 'thu', short: 'Thu', date: '26', weekend: false },
  { id: 'fri', short: 'Fri', date: '27', weekend: false },
  { id: 'sat', short: 'Sat', date: '28', weekend: true },
  { id: 'sun', short: 'Sun', date: '29', weekend: true },
]

export const weekLabel = '23–29 November 2026'

/** Minimum people on each shift: two on weekdays, one at weekends */
export const required = (day: Day): Record<CoveredShift, number> =>
  day.weekend
    ? { early: 1, late: 1, night: 1 }
    : { early: 2, late: 2, night: 1 }

export interface Person {
  id: string
  name: string
  role: string
  /** Contracted hours per week */
  contract: number
}

export const people: Person[] = [
  { id: 'amara', name: 'Amara Okafor', role: 'Charge nurse', contract: 40 },
  { id: 'luis', name: 'Luis Herrera', role: 'Nurse', contract: 40 },
  { id: 'hana', name: 'Hana Sato', role: 'Nurse', contract: 24 },
  { id: 'tom', name: 'Tom Becker', role: 'Nurse', contract: 40 },
  { id: 'priya', name: 'Priya Nair', role: 'Nurse', contract: 24 },
  { id: 'jonas', name: 'Jonas Lind', role: 'Care assistant', contract: 40 },
  { id: 'chloe', name: 'Chloe Martin', role: 'Care assistant', contract: 40 },
  { id: 'sam', name: 'Sam Reyes', role: 'Care assistant', contract: 32 },
]

/** Each person's week, Monday to Sunday */
export type Schedule = Record<string, Assignment[]>

const E = 'early'
const L = 'late'
const N = 'night'
const A = 'leave'
const _ = null

/**
 * A draft with problems left in on purpose: Monday is one short on the late
 * shift and Saturday has nobody on it, Tom goes from a late straight into an
 * early (8h rest), and Jonas is booked 8h over his contract. Tom has the
 * hours to cover Saturday.
 */
export const draft: Schedule = {
  amara: [E, E, E, E, E, _, _],
  luis: [L, _, L, L, _, E, E],
  hana: [_, E, _, E, E, _, _],
  tom: [_, L, E, _, L, _, _],
  priya: [N, N, N, _, _, _, _],
  jonas: [E, L, L, L, L, _, L],
  chloe: [A, A, A, A, A, _, _],
  sam: [_, _, _, N, N, N, N],
}

import { covered, days, people, required, shiftById, shifts } from './data'
import type { Assignment, CoveredShift, Person, Schedule } from './data'

/** Fewer hours than this between two shifts breaks the rest rule */
export const MIN_REST = 11

export const cellKey = (personId: string, day: number) => `${personId}:${day}`

/** Sets one person's day, without touching the rest */
export function assign(
  schedule: Schedule,
  personId: string,
  day: number,
  value: Assignment,
): Schedule {
  if (schedule[personId][day] === value) return schedule
  const week = [...schedule[personId]]
  week[day] = value
  return { ...schedule, [personId]: week }
}

/** Scheduled hours in the week, leave included */
export const hours = (week: Assignment[]) =>
  week.reduce((sum, a) => sum + (a ? shiftById[a].hours : 0), 0)

/** How many people work each shift on a day */
export function coverage(schedule: Schedule, day: number) {
  const count = { early: 0, late: 0, night: 0 } as Record<CoveredShift, number>
  for (const person of people) {
    const a = schedule[person.id][day]
    if (a && a !== 'leave') count[a]++
  }
  return count
}

export interface Gap {
  day: number
  shift: CoveredShift
  have: number
  need: number
}

/** Every shift with fewer people than it needs */
export const gaps = (schedule: Schedule): Gap[] =>
  days.flatMap((d, day) => {
    const have = coverage(schedule, day)
    const need = required(d)
    return covered
      .filter((shift) => have[shift] < need[shift])
      .map((shift) => ({ day, shift, have: have[shift], need: need[shift] }))
  })

/**
 * Hours of rest before the shift on `day`, counted from the end of the
 * previous day's shift. Null when either day isn't a worked shift.
 */
export function restBefore(week: Assignment[], day: number): number | null {
  const prev = week[day - 1]
  const next = week[day]
  if (!prev || !next || prev === 'leave' || next === 'leave') return null
  return 24 + shiftById[next].start - shiftById[prev].end
}

export interface Conflict {
  personId: string
  day: number
  rest: number
}

/** Shifts that start too soon after the one before */
export const conflicts = (schedule: Schedule): Conflict[] =>
  people.flatMap((person) =>
    days.flatMap((_, day) => {
      const rest = restBefore(schedule[person.id], day)
      return rest !== null && rest < MIN_REST
        ? [{ personId: person.id, day, rest }]
        : []
    }),
  )

/** Hours against contract: under, on or over */
export function load(person: Person, week: Assignment[]) {
  const h = hours(week)
  return {
    hours: h,
    diff: h - person.contract,
    status:
      h > person.contract ? 'over' : h < person.contract ? 'under' : 'exact',
  } as const
}

/** Cells that differ from the published schedule */
export function changes(saved: Schedule, current: Schedule) {
  const changed = new Set<string>()
  for (const person of people) {
    current[person.id].forEach((a, day) => {
      if (saved[person.id][day] !== a) changed.add(cellKey(person.id, day))
    })
  }
  return changed
}

/** A typed key's assignment: a shift's letter, or Delete/Backspace for off */
export function fromKey(key: string): Assignment | undefined {
  if (key === 'Delete' || key === 'Backspace') return null
  return shifts.find((s) => s.code === key.toUpperCase())?.id
}

import { useState } from 'react'
import type { KeyboardEvent } from 'react'
import { Check, TriangleAlert } from 'lucide-react'

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { cn } from '#/lib/utils'
import { shiftById, shifts } from './data'
import type { Assignment, ShiftId } from './data'

export const shiftTone: Record<ShiftId, string> = {
  early: 'bg-sky-100 text-sky-900 dark:bg-sky-500/20 dark:text-sky-200',
  late: 'bg-amber-100 text-amber-900 dark:bg-amber-500/20 dark:text-amber-200',
  night:
    'bg-violet-100 text-violet-900 dark:bg-violet-500/25 dark:text-violet-200',
  leave:
    'bg-[repeating-linear-gradient(135deg,var(--muted)_0_4px,transparent_4px_8px)] text-muted-foreground',
}

/** A shift's letter in its color, as in the cells and the legend */
export function ShiftChip({
  shift,
  className,
}: {
  shift: ShiftId
  className?: string
}) {
  return (
    <span
      aria-hidden
      className={cn(
        'inline-flex size-5 shrink-0 items-center justify-center rounded text-[11px] font-semibold',
        shiftTone[shift],
        className,
      )}
    >
      {shiftById[shift].code}
    </span>
  )
}

const options: { value: Assignment; label: string; time: string }[] = [
  ...shifts.map((s) => ({ value: s.id, label: s.label, time: s.time })),
  { value: null, label: 'Off', time: 'Not working' },
]

export function ShiftCell({
  cellKey,
  value,
  label,
  changed,
  rest,
  tabbable,
  onAssign,
  onKeyDown,
}: {
  /** Lets the table find this cell to move focus to it */
  cellKey: string
  value: Assignment
  /** Who and which day, for screen readers: "Tom Becker, Wed 25" */
  label: string
  changed: boolean
  /** Hours of rest before this shift when it's too few, otherwise null */
  rest: number | null
  /** Roving tabindex: only the grid's current cell is in the tab order */
  tabbable: boolean
  onAssign: (value: Assignment) => void
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void
}) {
  const [open, setOpen] = useState(false)
  const shift = value ? shiftById[value] : null

  const description = [
    shift ? `${shift.label}, ${shift.time}` : 'Off',
    rest !== null ? `only ${rest}h rest after the previous shift` : null,
    changed ? 'changed' : null,
  ]
    .filter(Boolean)
    .join('; ')

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          data-cell={cellKey}
          tabIndex={tabbable ? 0 : -1}
          aria-label={`${label}: ${description}`}
          title={
            rest !== null
              ? `Only ${rest}h rest since the previous shift (11h minimum)`
              : undefined
          }
          onKeyDown={onKeyDown}
          className={cn(
            'group/cell relative flex h-11 w-full min-w-14 items-center justify-center rounded-md text-xs font-semibold outline-none',
            'focus-visible:ring-[3px] focus-visible:ring-ring/60',
            shift
              ? shiftTone[shift.id]
              : 'text-muted-foreground/40 hover:bg-muted hover:text-muted-foreground',
            rest !== null && 'ring-2 ring-destructive ring-inset',
          )}
        >
          {shift ? (
            shift.code
          ) : (
            <span aria-hidden className="group-hover/cell:hidden">
              –
            </span>
          )}
          {shift ? null : (
            <span aria-hidden className="hidden group-hover/cell:inline">
              +
            </span>
          )}
          {rest !== null ? (
            <TriangleAlert
              aria-hidden
              className="absolute top-1 left-1 size-3 text-destructive"
            />
          ) : null}
          {changed ? (
            <span
              aria-hidden
              className="absolute top-1 right-1 size-1.5 rounded-full bg-blue-500"
            />
          ) : null}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="center"
        className="w-56 p-1"
        aria-label={`Shift for ${label}`}
        onOpenAutoFocus={(event) => {
          // Start on the current choice rather than the first one
          event.preventDefault()
          const current = (
            event.currentTarget as HTMLElement | null
          )?.querySelector<HTMLElement>('[aria-pressed="true"]')
          current?.focus()
        }}
        onKeyDown={(event) => {
          if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return
          event.preventDefault()
          const items = [
            ...event.currentTarget.querySelectorAll<HTMLElement>('button'),
          ]
          const i = items.indexOf(document.activeElement as HTMLElement)
          const next = event.key === 'ArrowDown' ? i + 1 : i - 1
          items[(next + items.length) % items.length]?.focus()
        }}
      >
        <p className="px-2 pt-1 pb-1.5 text-xs text-muted-foreground">
          {label}
        </p>
        {options.map((option) => (
          <button
            key={option.label}
            type="button"
            aria-pressed={option.value === value}
            onClick={() => {
              onAssign(option.value)
              setOpen(false)
            }}
            className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-left text-sm outline-none hover:bg-accent focus-visible:bg-accent"
          >
            {option.value ? (
              <ShiftChip shift={option.value} />
            ) : (
              <span
                aria-hidden
                className="inline-flex size-5 items-center justify-center rounded border border-dashed text-[11px] text-muted-foreground"
              >
                –
              </span>
            )}
            <span className="flex-1">{option.label}</span>
            <span className="text-xs text-muted-foreground tabular-nums">
              {option.time}
            </span>
            <Check
              aria-hidden
              className={cn(
                'size-4',
                option.value === value ? 'opacity-100' : 'opacity-0',
              )}
            />
          </button>
        ))}
        <p className="mt-1 border-t px-2 pt-1.5 pb-1 text-xs text-muted-foreground">
          Or type E, L, N, A on a cell. Delete clears it.
        </p>
      </PopoverContent>
    </Popover>
  )
}

import type { KeyboardEvent } from 'react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { cn } from '#/lib/utils'
import { covered, days, required, shiftById } from './data'
import type { Assignment, Person, Schedule } from './data'
import { MIN_REST, cellKey, coverage, load, restBefore } from './schedule'
import { ShiftCell, ShiftChip } from './shift-cell'

export interface ScheduleMeta {
  schedule: Schedule
  /** Cell keys that differ from the published schedule */
  changed: Set<string>
  /** The cell that's in the tab order */
  active: string
  assign: (personId: string, day: number, value: Assignment) => void
  /** Arrow keys, letters and Delete on a cell; handled by the table */
  onCellKeyDown: (
    event: KeyboardEvent<HTMLButtonElement>,
    personId: string,
    day: number,
  ) => void
}

const getMeta = (table: Table<Person>) =>
  table.options.meta as unknown as ScheduleMeta

export const columns: ColumnDef<Person>[] = [
  {
    id: 'person',
    header: 'Staff',
    cell: ({ row }) => (
      <div className="flex min-w-0 flex-col">
        <span className="truncate font-medium">{row.original.name}</span>
        <span className="truncate text-xs text-muted-foreground">
          {row.original.role}
        </span>
      </div>
    ),
    footer: () => (
      <div className="flex flex-col text-xs">
        <span className="font-medium">On shift</span>
        <span className="text-muted-foreground">of needed</span>
      </div>
    ),
  },
  ...days.map((d, day): ColumnDef<Person> => ({
    id: d.id,
    header: () => (
      <div className="flex flex-col items-center leading-tight">
        <span>{d.short}</span>
        <span className="text-xs font-normal text-muted-foreground tabular-nums">
          {d.date}
        </span>
      </div>
    ),
    cell: ({ row, table }) => {
      const meta = getMeta(table)
      const person = row.original
      const week = meta.schedule[person.id]
      const rest = restBefore(week, day)
      const key = cellKey(person.id, day)
      return (
        <ShiftCell
          cellKey={key}
          value={week[day]}
          label={`${person.name}, ${d.short} ${d.date}`}
          changed={meta.changed.has(key)}
          rest={rest !== null && rest < MIN_REST ? rest : null}
          tabbable={meta.active === key}
          onAssign={(value) => meta.assign(person.id, day, value)}
          onKeyDown={(event) => meta.onCellKeyDown(event, person.id, day)}
        />
      )
    },
    footer: ({ table }) => {
      const have = coverage(getMeta(table).schedule, day)
      const need = required(d)
      return (
        <ul className="flex flex-col items-center gap-0.5 text-xs tabular-nums">
          {covered.map((shift) => {
            const short = have[shift] < need[shift]
            return (
              <li
                key={shift}
                className={cn(
                  'flex items-center gap-1',
                  short && 'font-semibold text-destructive',
                )}
              >
                <ShiftChip shift={shift} className="size-4 text-[10px]" />
                <span className="sr-only">{shiftById[shift].label}:</span>
                {have[shift]}/{need[shift]}
                {short ? <span className="sr-only">(short)</span> : null}
              </li>
            )
          })}
        </ul>
      )
    },
  })),
  {
    id: 'hours',
    header: () => <span className="block text-right">Hours</span>,
    cell: ({ row, table }) => {
      const person = row.original
      const { hours, diff, status } = load(
        person,
        getMeta(table).schedule[person.id],
      )
      return (
        <div className="flex min-w-20 flex-col items-end gap-1">
          <span className="text-sm tabular-nums">
            {hours}
            <span className="text-muted-foreground"> / {person.contract}h</span>
          </span>
          <span
            className={cn(
              'text-xs tabular-nums',
              status === 'over'
                ? 'font-medium text-amber-700 dark:text-amber-400'
                : 'text-muted-foreground',
            )}
          >
            {status === 'exact'
              ? 'On contract'
              : status === 'over'
                ? `${diff}h over`
                : `${-diff}h free`}
          </span>
        </div>
      )
    },
  },
]

import { useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { ScheduleMeta } from './columns'
import { days, people } from './data'
import type { Assignment, Schedule } from './data'
import { cellKey, fromKey } from './schedule'

const isDay = (id: string) => days.some((d) => d.id === id)
const weekend = (id: string) => days.find((d) => d.id === id)?.weekend

export function ScheduleTable({
  schedule,
  changed,
  assign,
}: {
  schedule: Schedule
  changed: Set<string>
  assign: (personId: string, day: number, value: Assignment) => void
}) {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(cellKey(people[0].id, 0))

  function focusCell(row: number, day: number) {
    const r = Math.max(0, Math.min(people.length - 1, row))
    const d = Math.max(0, Math.min(days.length - 1, day))
    const key = cellKey(people[r].id, d)
    setActive(key)
    ref.current?.querySelector<HTMLElement>(`[data-cell="${key}"]`)?.focus()
  }

  function onCellKeyDown(
    event: KeyboardEvent<HTMLButtonElement>,
    personId: string,
    day: number,
  ) {
    if (event.metaKey || event.ctrlKey || event.altKey) return
    const row = people.findIndex((p) => p.id === personId)
    const move: Record<string, [number, number]> = {
      ArrowUp: [row - 1, day],
      ArrowDown: [row + 1, day],
      ArrowLeft: [row, day - 1],
      ArrowRight: [row, day + 1],
      Home: [row, 0],
      End: [row, days.length - 1],
    }
    if (event.key in move) {
      event.preventDefault()
      focusCell(...move[event.key])
      return
    }
    const value = fromKey(event.key)
    if (value === undefined) return
    event.preventDefault()
    assign(personId, day, value)
    // Typing a shift moves on to the next day, so a week fills in one go
    if (value !== null) focusCell(row, day + 1)
  }

  const meta: ScheduleMeta = {
    schedule,
    changed,
    active,
    assign,
    onCellKeyDown,
  }

  const table = useReactTable({
    data: people,
    columns,
    getRowId: (person) => person.id,
    getCoreRowModel: getCoreRowModel(),
    meta,
  })

  const sticky = 'sticky left-0 z-10 bg-background'

  return (
    <div
      ref={ref}
      // Whichever cell gets focus, by click or by Tab, becomes the tab stop
      onFocus={(event) => {
        const key = (event.target as HTMLElement).dataset.cell
        if (key) setActive(key)
      }}
      className="overflow-x-auto rounded-md border"
    >
      <Table className="min-w-[760px] table-fixed">
        <colgroup>
          <col className="w-32 sm:w-48" />
          {days.map((d) => (
            <col key={d.id} />
          ))}
          <col className="w-28" />
        </colgroup>
        <TableHeader>
          {table.getHeaderGroups().map((group) => (
            <TableRow key={group.id} className="hover:bg-transparent">
              {group.headers.map((header) => (
                <TableHead
                  key={header.id}
                  className={cn(
                    'h-auto py-2',
                    header.column.id === 'person' && sticky,
                    isDay(header.column.id) && 'text-center',
                    weekend(header.column.id) && 'bg-muted/50',
                  )}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow key={row.id} className="hover:bg-transparent">
              {row.getVisibleCells().map((cell) => (
                <TableCell
                  key={cell.id}
                  className={cn(
                    isDay(cell.column.id) ? 'p-1' : 'py-1.5',
                    cell.column.id === 'person' && sticky,
                    weekend(cell.column.id) && 'bg-muted/50',
                  )}
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
        <TableFooter className="bg-transparent">
          {table
            .getFooterGroups()
            .slice(0, 1)
            .map((group) => (
              <TableRow key={group.id} className="hover:bg-transparent">
                {group.headers.map((header) => (
                  <TableCell
                    key={header.id}
                    className={cn(
                      'py-2 align-top',
                      header.column.id === 'person' && sticky,
                      weekend(header.column.id) && 'bg-muted/50',
                    )}
                  >
                    {flexRender(
                      header.column.columnDef.footer,
                      header.getContext(),
                    )}
                  </TableCell>
                ))}
              </TableRow>
            ))}
        </TableFooter>
      </Table>
    </div>
  )
}
